window.SITE_DATA = {"project":{"@context":{"@vocab":"https://schema.org/","tg":"https://theupskillinglabs.github.io/triangles/ns#","tier":"tg:tier","x":"tg:x","y":"tg:y","w":"tg:w","h":"tg:h","verified":"tg:verified","locked":"tg:locked","strong":"tg:strong","source_url":"tg:sourceUrl","children":{"@id":"tg:hasChild","@type":"@id"}},"title":"Civics & Elections: Signal Pool","concept":"","generatedAt":"2026-07-25T20:34:31.702Z","@graph":[{"@id":"item_86c16dd7-803d-4de3-bb83-16ac8ccb93a3","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Truths / Facts","description":"are not shared across groups","x":2956,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_c3ffe555-dd7f-4e7c-aa25-59dbf548eea3","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Access to information","description":"about local candidate records is not easy to find (self-reported)","x":0,"y":300,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_ac4140f1-032a-4ed8-974d-e7a74c5dd4fe","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Finding hyper-local","description":"community engagement is hard","x":7028,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_21840627-7901-4d3c-a896-c645111c3279","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Organizing individual volunteers","description":"is a labor intensive process w/ lots of attrition","x":296,"y":300,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_558a3c99-862d-45c1-b33a-e95fcef51102","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Equality of representation","description":"gerrymandering voters are not equally represented","x":10192,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_5736cc04-fae6-40f2-93f5-6ecd32be8bd3","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Participation apathy","description":"voter turnout is low","x":10784,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_01","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Restructuring the Political System","description":"A high-level desire to shift the fundamental political structure of the United States to model other international systems.","x":592,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-1","children":[]},{"@id":"item_02","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Media Misinformation","description":"Broad concerns regarding how misleading media and digital influencing are negatively impacting civic engagement.","x":2660,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-3","children":[]},{"@id":"item_03","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Campaign Finance & District Competitiveness","description":"Observations that financial influence and gerrymandering have reduced the competitiveness of congressional districts.","x":6028,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-4","children":[]},{"@id":"item_04","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Ranked Choice Voting Education","description":"The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.","x":9488,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-5","children":[]},{"@id":"item_05","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Targeting Legislative Influence","description":"It is currently too labor-intensive and expensive to identify the most effective individuals or groups to lobby specific legislators on specific issues at the right time.","x":888,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-6","children":[]},{"@id":"item_06","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Local Candidate Information Gaps","description":"Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.","x":5028,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-7","children":[]},{"@id":"item_07","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Public Engagement on Government AI","description":"Citizens lack the tools and platforms to provide feedback on or inform how government agencies and companies deploy artificial intelligence in their communities.","x":1184,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-8","children":[]},{"@id":"item_08","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Recycling Contamination & Civic Decay","description":"Improper recycling in public spaces leads to systemic waste and creates a visible, self-perpetuating belief that responsible civic behavior doesn't matter.","x":1480,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-9","children":[]},{"@id":"item_09","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Campaign Finance","description":"Reform efforts consistently hit roadblocks like the Citizens United decision.","x":5732,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-10","children":[]},{"@id":"item_10","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Civic Distrust & Disinformation","description":"A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.","x":704,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-11","children":[]},{"@id":"item_11","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Logistical & Educational Barriers to Voting","description":"Voting is burdened by physical hurdles (childcare, time off work) and a lack of plain-language education on how local elections directly impact citizens' daily lives.","x":8600,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-12","children":[]},{"@id":"item_12","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"The Death of Political Compromise","description":"The electorate and activists are failing to recognize that compromise is a fundamental component of democracy, negatively impacting civic engagement.","x":1776,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-13","children":[]},{"@id":"item_13","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Civics Talent Pipeline Shortage","description":"There is a noticeable shortage of talent to fill junior roles within the civics and elections workforce.","x":0,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-14","children":[]},{"@id":"item_14","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"False Transparency in Government","description":"Government agencies and schools exhibit a disconnect with their constituencies, presenting a 'false flag' of transparency that leaves communities feeling ignored without understanding how aggregate sentiment is utilized.","x":5436,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-15","children":[]},{"@id":"item_15","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"AI Bot Interference in Constituent Engagement","description":"Artificial intelligence is being used to flood communication channels, rendering actual, organic constituent engagement ineffective.","x":1302,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-16","children":[]},{"@id":"item_16","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Hopelessness & Lack of Election Information","description":"Voters feel hopeless and lack basic awareness of when local elections occur, relying on passive information like mailers or word of mouth.","x":2364,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-17","children":[]},{"@id":"item_17","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Structural Election Imbalances","description":"The current electoral system features gerrymandering, dominant two-party privileges, and districts so large that politicians effectively choose their voters.","x":3844,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-18","children":[]},{"@id":"item_18","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Political Bubbles & NIMBYism","description":"Citizens are highly polarized and isolated in social bubbles, proposing solutions or pushing back on reforms without understanding the broader impacts, trade-offs, or equity implications beyond their circles.","x":2072,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-19","children":[]},{"@id":"item_19","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Volunteer Burnout & Knowledge Transfer","description":"Local volunteer roles, such as PTA leadership, fall on a few individuals. There is a need for tools to reduce the operational burden and retain institutional knowledge as volunteer leadership turns over.","x":2368,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-19","children":[]},{"@id":"item_20","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Aging Civic Leadership","description":"Local civic organizations are heavily reliant on aging populations for leadership and membership, struggling to recruit younger generations who face competing career and family priorities.","x":2664,"y":300,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-20","children":[]},{"@id":"item_21","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Uncontested Local Candidate Transparency","description":"It is incredibly difficult to research the records of local election candidates, especially those running uncontested or without a communications budget, leaving voters feeling uninformed.","x":0,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-21","children":[]},{"@id":"item_22","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Unexplained Ballot Roles","description":"Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.","x":8896,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-22","children":[]},{"@id":"item_23","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Performative Bipartisanship","description":"Statements, town halls, and pledges perform collaboration without doing it; missing is a structured, sprint-like way for people who are supposed to disagree to define a shared problem and build something together.","x":296,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-23","children":[]},{"@id":"item_24","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Loneliness as a Civic Problem","description":"The social scaffolding that once created accountability in how people form relationships has dissolved with nothing replacing it — an isolation epidemic treated as a private matter rather than missing civic infrastructure.","x":7324,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-24","children":[]},{"@id":"item_25","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Outdated Small-Organization Elections","description":"Unions, HOAs, and nonprofit boards run consequential elections on paper ballots and opaque spreadsheets; available tools serve incumbent leadership rather than transparent, verifiable results for members.","x":6732,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-25","children":[]},{"@id":"item_26","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Eroded Respect for Disagreement","description":"People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.","x":2068,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-26","children":[]},{"@id":"item_27","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Misunderstood Pace of Government","description":"Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.","x":4140,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-27","children":[]},{"@id":"item_28","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Cross-Jurisdiction Election Distrust","description":"Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.","x":3252,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-28","children":[]},{"@id":"item_29","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"No Playbook for Good Citizenship","description":"There is no clear guide to the daily, weekly, and monthly steps of being an informed, participating citizen — the information is scattered everywhere, and the whole project feels overwhelming.","x":296,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-29","children":[]},{"@id":"item_30","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Broad Civic Disengagement","description":"Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.","x":4436,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-30","children":[]},{"@id":"item_31","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Missing Dialogue Across Difference","description":"People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.","x":1772,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-31","children":[]},{"@id":"item_32","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Untapped Personal Megaphones","description":"People forget how influential they can be with the biggest megaphone in history in the palm of their hand — but no one has cracked engagement at scale without it devolving into a rage machine.","x":592,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-32","children":[]},{"@id":"item_33","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Low-Information Voting & Gerrymandering","description":"Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.","x":3548,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-33","children":[]},{"@id":"item_34","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Ranked-Choice Confusion Persists","description":"Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.","x":9784,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-34","children":[]},{"@id":"item_35","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Anemic, Uneven Participation","description":"Civic participation is thin, and only some voices get heard and lifted.","x":11080,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-35","children":[]},{"@id":"item_36","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Constituent Mail Black Hole","description":"Letters and emails to representatives feel like talking into a void — heartfelt messages come back as generic, strategist-polished boilerplate.","x":11488,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-36","children":[]},{"@id":"item_37","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Entertainment Crowds Out Civic Attention","description":"Citizens are too busy consuming entertainment to pay attention to neighborhood issues, kids' activities, or their government; outreach across multiple mediums still meets 'I don't have time'.","x":1006,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-37","children":[]},{"@id":"item_38","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Complacency & Candidate Deterrence","description":"The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.","x":4732,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-38","children":[]},{"@id":"item_39","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Calls for Stricter Ballot ID","description":"A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.","x":9192,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-39","children":[]},{"@id":"item_40","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Women Still Under-Represented","description":"Women remain under-represented in political leadership, even as women run for the highest offices.","x":10488,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-40","children":[]},{"@id":"item_41","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Student Technology Access Gap","description":"Students lack access to equipment for training, and school technology funding isn't keeping up; grassroots fundraisers and lobbying for federal funding only go so far.","x":888,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-41","children":[]},{"@id":"item_42","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Mid-Decade Redistricting Shifts","description":"California, Missouri, North Carolina, and Texas will use different congressional maps in 2026 than in 2024 due to voluntary mid-decade redistricting — unusual, and worth watching for how it shifts competitive-district counts.","x":1184,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-42","children":[]},{"@id":"item_43","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Accountability for Public Lies","description":"Telling the truth — and holding liars accountable and responsible — is named as the missing piece of civic life.","x":8192,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-43","children":[]},{"@id":"item_44","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Cross-Agency Coordination Failure","description":"Constituent problems take years to solve because coordinating local, federal, and neighboring-state agencies, private entities, and residents is nearly impossible — stakeholders claim jurisdiction for credit and duck it for problem-solving, at great cost to unpaid commissioners.","x":12080,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-44","children":[]},{"@id":"item_45","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Sidewalks vs. Micromobility","description":"DC sidewalks are increasingly dangerous for elderly, young, and disabled pedestrians as motorized bikes and scooters — often ridden illegally — collide with the city's walkability promise; other cities' regulations may hold lessons.","x":1480,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-45","children":[]},{"@id":"item_46","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Representatives Without Accountability","description":"Representatives don't seem to answer to the people, and replacing them changes little — new reps inherit the same voting patterns, with the two-party system and polarization at the crux.","x":7896,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-46","children":[]},{"@id":"item_47","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Last-Mile Resource Disconnect","description":"Programs, grants, and services exist on paper, but communities often don't know about them or can't navigate them — the gap is grassroots outreach, trusted local partners, and hands-on navigation support, not new programs.","x":11784,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-47","children":[]},{"@id":"item_48","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Campus–Neighborhood Disconnection","description":"There is no single, easy channel for a university community and its neighbors to trade information and opportunities — student jobs, local events, programs, and campus resources live in scattered slices.","x":6436,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-48","children":[]},{"@id":"item_5d50f77c-901a-43de-811f-e4709ba6c4f3","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Economist?","description":"Generally officals and SMEs certainty even when problems/solutions are uncertain","x":12376,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_b649713f-ac00-417e-a0e8-f4ce7c0577f9","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Voter Turnout?","description":"Declining or uneven participation rates across electorate demographics","x":1776,"y":475,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_c5ed4538-18c1-4e16-8898-5d028a8e8398","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Rational ignorance","description":"Individually rational to stay uninformed since one vote is rarely decisive, voting is a collective action problem","x":14152,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_8e0887ed-8282-4594-b86c-eeb1546cf7c4","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Elected officials make election policy","description":"Convergence of Elected Officials and election policy","x":2072,"y":475,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_dd50f501-2ac0-4d60-bd60-6f0d726e51d7","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Access to Engagement","description":"Across demos","x":13856,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_a85dd0dd-2a9a-4f82-990b-9513ccd27b29","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Information Asymmetry?","description":"Hard to find out about local elections; too much national/federal","x":12968,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_13da2d54-a4f9-48f5-8326-125c3eab8afd","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Literacy Rates","description":"Baseline reading/civic literacy needed to navigate ballots and information","x":12672,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_2d228eb1-0ec9-4702-bc3c-bed06ac2f8d2","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Democratization of Public Opinion Data","description":"Public opinion is essentials to hold policy makers accountable to constituents but the data is not public","x":14448,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_d0b5d166-5503-418c-98f1-50d05b2cf460","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Shared Truth - or Spaces for Information","description":"Lack of common spaces or sources for shared factual information","x":13264,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_50d01948-6299-42b6-98a6-2927f3ed2dc7","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Public Engagement","description":"Public engagement is uneven or nonexistent particularly at the local level","x":2368,"y":475,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"item_b492e0a2-6e26-422c-8246-4d8bd7077e3a","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Low Local Action","description":"People don't have the time or information to determine what civic actions are 'worth it'.","x":13560,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"","children":[]},{"@id":"item_1ec68967-1e6e-4ce0-97c6-89dfc3bb92e2","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Media Misinformation","description":"Broad concerns regarding how misleading media and digital influencing are negatively impacting civic engagement.","x":2664,"y":475,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-3","children":[]},{"@id":"item_8871c4a9-0b9b-4699-8aeb-a7ee01a5792d","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Campaign Finance & District Competitiveness","description":"Observations that financial influence and gerrymandering have reduced the competitiveness of congressional districts.","x":0,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-4","children":[]},{"@id":"item_0aa0041a-a5ba-4a39-8ce0-d20702537235","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Ranked Choice Voting Education","description":"The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.","x":16040,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-5","children":[]},{"@id":"item_27e556fa-936c-438d-93db-b3feacf2cebf","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Targeting Legislative Influence","description":"It is currently too labor-intensive and expensive to identify the most effective individuals or groups to lobby specific legislators on specific issues at the right time.","x":296,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-6","children":[]},{"@id":"item_a684b0d7-d40a-4ed9-a403-d1f5d0a779a2","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Local Candidate Information Gaps","description":"Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.","x":14856,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-7","children":[]},{"@id":"item_e45b001b-b705-40df-a2f0-2d39e4fcae27","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Public Engagement on Government AI","description":"Citizens lack the tools and platforms to provide feedback on or inform how government agencies and companies deploy artificial intelligence in their communities.","x":592,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-8","children":[]},{"@id":"item_986fd3d2-f54b-44ab-89ef-3beb4a18135e","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Civic Distrust & Disinformation","description":"A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.","x":15152,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-11","children":[]},{"@id":"item_9df035c3-6f65-4085-99ca-e81c32c930b6","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Logistical & Educational Barriers to Voting","description":"Voting is burdened by physical hurdles (childcare, time off work) and a lack of plain-language education on how local elections directly impact citizens' daily lives.","x":888,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-12","children":[]},{"@id":"item_23e48421-6e7c-4b65-80bb-f54cb387b15d","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"The Death of Political Compromise","description":"The electorate and activists are failing to recognize that compromise is a fundamental component of democracy, negatively impacting civic engagement.","x":1184,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-13","children":[]},{"@id":"item_9cf036c5-7d18-41e0-bf7e-d07ce0758620","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Civics Talent Pipeline Shortage","description":"There is a noticeable shortage of talent to fill junior roles within the civics and elections workforce.","x":1480,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-14","children":[]},{"@id":"item_473baf65-c6f9-46f5-bbbc-dfb0d43cbe0a","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"False Transparency in Government","description":"Government agencies and schools exhibit a disconnect with their constituencies, presenting a 'false flag' of transparency that leaves communities feeling ignored without understanding how aggregate sentiment is utilized.","x":1776,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-15","children":[]},{"@id":"item_5fdeb78e-e590-45d8-89b1-5da9da8cb3e3","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"AI Bot Interference in Constituent Engagement","description":"Artificial intelligence is being used to flood communication channels, rendering actual, organic constituent engagement ineffective.","x":2072,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-16","children":[]},{"@id":"item_5ca85dfa-d7d4-48a9-b763-f6eab4b6997a","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Hopelessness & Lack of Election Information","description":"Voters feel hopeless and lack basic awareness of when local elections occur, relying on passive information like mailers or word of mouth.","x":2368,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-17","children":[]},{"@id":"item_c2265fd6-a117-4756-a348-b19d5259afad","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Structural Election Imbalances","description":"The current electoral system features gerrymandering, dominant two-party privileges, and districts so large that politicians effectively choose their voters.","x":2664,"y":650,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-18","children":[]},{"@id":"item_686bd123-41c3-4797-b964-5dae0d6a6095","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Volunteer Burnout & Knowledge Transfer","description":"Local volunteer roles, such as PTA leadership, fall on a few individuals. There is a need for tools to reduce the operational burden and retain institutional knowledge as volunteer leadership turns over.","x":0,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-19","children":[]},{"@id":"item_6a0735fa-676f-484f-a787-56ed9b2e30ca","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Aging Civic Leadership","description":"Local civic organizations are heavily reliant on aging populations for leadership and membership, struggling to recruit younger generations who face competing career and family priorities.","x":296,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-20","children":[]},{"@id":"item_144b0c94-417c-40a2-959a-2891eb35cee0","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Uncontested Local Candidate Transparency","description":"It is incredibly difficult to research the records of local election candidates, especially those running uncontested or without a communications budget, leaving voters feeling uninformed.","x":592,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-21","children":[]},{"@id":"item_40d34589-7297-4a03-8d2a-64eabd41a443","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Unexplained Ballot Roles","description":"Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.","x":888,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-22","children":[]},{"@id":"item_9e9aef80-ea75-4a3a-b6a5-49292dd61cd4","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Performative Bipartisanship","description":"Statements, town halls, and pledges perform collaboration without doing it; missing is a structured, sprint-like way for people who are supposed to disagree to define a shared problem and build something together.","x":1184,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-23","children":[]},{"@id":"item_34f070a3-2ed0-4792-b2d8-d3397810d4de","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Loneliness as a Civic Problem","description":"The social scaffolding that once created accountability in how people form relationships has dissolved with nothing replacing it — an isolation epidemic treated as a private matter rather than missing civic infrastructure.","x":1480,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-24","children":[]},{"@id":"item_2130a814-640b-43c2-8275-307a1640718c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Outdated Small-Organization Elections","description":"Unions, HOAs, and nonprofit boards run consequential elections on paper ballots and opaque spreadsheets; available tools serve incumbent leadership rather than transparent, verifiable results for members.","x":1776,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-25","children":[]},{"@id":"item_a791403f-1820-45b5-9267-efcde34b5511","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Eroded Respect for Disagreement","description":"People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.","x":2072,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-26","children":[]},{"@id":"item_08f562c3-ba3c-40ea-a9ab-192bb9997f0c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Misunderstood Pace of Government","description":"Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.","x":2368,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-27","children":[]},{"@id":"item_dde238e4-8272-4bed-9529-297e65dfa54b","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Cross-Jurisdiction Election Distrust","description":"Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.","x":2664,"y":825,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-28","children":[]},{"@id":"item_d339162d-e40a-44c5-ac3c-3e93f6f5e66c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"No Playbook for Good Citizenship","description":"There is no clear guide to the daily, weekly, and monthly steps of being an informed, participating citizen — the information is scattered everywhere, and the whole project feels overwhelming.","x":0,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-29","children":[]},{"@id":"item_2941ce23-d56a-4b24-825b-eb110395caa8","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Broad Civic Disengagement","description":"Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.","x":296,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-30","children":[]},{"@id":"item_537c1574-b734-4363-8d27-735793813546","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Missing Dialogue Across Difference","description":"People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.","x":592,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-31","children":[]},{"@id":"item_69c563ec-3d96-4ecd-bb80-aad3f594255f","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Low-Information Voting & Gerrymandering","description":"Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.","x":888,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-33","children":[]},{"@id":"item_c5a4bf8a-1714-4719-ac31-fe1b72fa3a78","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Ranked-Choice Confusion Persists","description":"Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.","x":15744,"y":0,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-34","children":[]},{"@id":"item_6b789513-c9f9-485a-8bfa-7b6e3b024e79","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Anemic, Uneven Participation","description":"Civic participation is thin, and only some voices get heard and lifted.","x":1184,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-35","children":[]},{"@id":"item_f1fa5889-0259-4d0c-9aa9-aa2e0457177c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Constituent Mail Black Hole","description":"Letters and emails to representatives feel like talking into a void — heartfelt messages come back as generic, strategist-polished boilerplate.","x":1480,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-36","children":[]},{"@id":"item_e5c5cb45-71a0-46fe-b724-e6cc9d52f438","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Entertainment Crowds Out Civic Attention","description":"Citizens are too busy consuming entertainment to pay attention to neighborhood issues, kids' activities, or their government; outreach across multiple mediums still meets 'I don't have time'.","x":1776,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-37","children":[]},{"@id":"item_60a8f83b-e4c5-41b7-b225-d0762354b80c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Complacency & Candidate Deterrence","description":"The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.","x":2072,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-38","children":[]},{"@id":"item_dc82fbf7-3e87-4f6c-81c5-2539970cff96","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Calls for Stricter Ballot ID","description":"A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.","x":2368,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-39","children":[]},{"@id":"item_82140d58-addc-4b99-b95d-bbefb355ac77","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Women Still Under-Represented","description":"Women remain under-represented in political leadership, even as women run for the highest offices.","x":2664,"y":1000,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-40","children":[]},{"@id":"item_829d2513-ebec-411b-8916-0a012585a724","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Student Technology Access Gap","description":"Students lack access to equipment for training, and school technology funding isn't keeping up; grassroots fundraisers and lobbying for federal funding only go so far.","x":0,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-41","children":[]},{"@id":"item_8d7b0fdf-6ba0-49f3-9b41-2d4a850d94eb","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Mid-Decade Redistricting Shifts","description":"California, Missouri, North Carolina, and Texas will use different congressional maps in 2026 than in 2024 due to voluntary mid-decade redistricting — unusual, and worth watching for how it shifts competitive-district counts.","x":296,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-42","children":[]},{"@id":"item_6f6c3875-94d6-4ba6-a6aa-da4347c29114","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Accountability for Public Lies","description":"Telling the truth — and holding liars accountable and responsible — is named as the missing piece of civic life.","x":592,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-43","children":[]},{"@id":"item_a91d54bf-fa53-423e-90d5-4bd9537dd989","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Cross-Agency Coordination Failure","description":"Constituent problems take years to solve because coordinating local, federal, and neighboring-state agencies, private entities, and residents is nearly impossible — stakeholders claim jurisdiction for credit and duck it for problem-solving, at great cost to unpaid commissioners.","x":888,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-44","children":[]},{"@id":"item_da877880-c469-490a-8ffd-26b92aeb532c","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Representatives Without Accountability","description":"Representatives don't seem to answer to the people, and replacing them changes little — new reps inherit the same voting patterns, with the two-party system and polarization at the crux.","x":1184,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-46","children":[]},{"@id":"item_25fc7a13-a82b-4253-8357-fc5813e2af18","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Last-Mile Resource Disconnect","description":"Programs, grants, and services exist on paper, but communities often don't know about them or can't navigate them — the gap is grassroots outreach, trusted local partners, and hands-on navigation support, not new programs.","x":1480,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-47","children":[]},{"@id":"item_2049e6cc-b028-484b-a250-fd61e9b9eb4e","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"Campus–Neighborhood Disconnection","description":"There is no single, easy channel for a university community and its neighbors to trade information and opportunities — student jobs, local events, programs, and campus resources live in scattered slices.","x":1776,"y":1175,"w":240,"h":110,"verified":false,"strong":false,"source_url":"https://theupskillinglabs.org/survey/civics/results#r-48","children":[]},{"@id":"item_5e251afb-9e99-49b1-a4f7-b96ff10657f7","@type":"tg:SourceExtract","type":"Source Extract","tier":0,"title":"voter turnout","description":"people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation","x":15448,"y":0,"w":240,"h":110,"verified":true,"strong":false,"source_url":"","children":[]},{"@id":"card_9e883808-8899-43e8-8533-f62033a56f2d","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"","description":"","x":0,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_29","item_13"]},{"@id":"card_2ff004be-8293-4a87-947b-2ce4562bbac1","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Exhaustion of Cross-Ideological Tolerance","description":"Local stakeholders disengage from ideological opponents because active listening has vanished from public forums, rendering current participation tools largely ineffective.","x":2116,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_26","item_31"]},{"@id":"card_e115d2b4-9106-44e4-b2a9-13b7686cb9d5","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"","description":"","x":1780,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_15","item_31"]},{"@id":"card_d0ee16cd-ed1c-4c93-a0d0-a81f0f114b9f","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Digital Channels Alienating Polarized Constituents","description":"Differing political groups encounter AI-generated interference whenever they attempt online dialogue, driving them away from shared digital spaces. Consequently, new civic engagement tools only exacerbate isolation rather than bridging differences.","x":1444,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_15","item_31"]},{"@id":"card_dc734b4d-8db7-416e-9121-9ba49bd3d989","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Algorithmic Disruption Accelerating Stakeholder Exhaustion","description":"Polarized constituents attempting cross-ideological dialogue face automated channel flooding alongside social hostility, driving them to abandon shared civic spaces entirely.","x":2133,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_2ff004be-8293-4a87-947b-2ce4562bbac1","card_d0ee16cd-ed1c-4c93-a0d0-a81f0f114b9f","card_55a9290b-0ccf-4170-bc78-55ce9b5c3c5f"]},{"@id":"card_55a9290b-0ccf-4170-bc78-55ce9b5c3c5f","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Passive Awareness Meets Active Polarization","description":"Disengaged voters rely on passive, opportunistic information channels to learn about local elections while experiencing a civic culture that no longer tolerates ideological disagreement. As a result, alienation deepens into a total retreat from local democratic participation.","x":2452,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_16","item_26"]},{"@id":"card_48ac0422-747e-450c-ac9c-7c61b5007a00","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Structural Partisanship Distorts Electoral Legitimacy","description":"Structural features like gerrymandering and voting rules reinforce partisan boundaries, causing voters to view routine out-of-jurisdiction election procedures through a lens of partisan threat.","x":3460,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_33","item_28"]},{"@id":"card_772bd853-8b69-42f2-b487-be7915a80117","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Information Friction in Civic Power","description":"Voters and stretched legislative staff operate without a shared baseline of who holds power and how fast it moves, causing civic outreach tools to fail at bridging the gap.","x":4132,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_30","item_27"]},{"@id":"card_a168d595-bfad-40f1-9abb-1b65539b7c92","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"High-Risk, Low-Information Civic Spaces","description":"Citizens and potential leaders experience local politics as an opaque, media-dominated environment, driving voter apathy and self-selection out of public leadership.","x":4522,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_06","item_38"]},{"@id":"card_4f8e239a-3235-42f3-bccf-78df947d901a","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"High-Risk, Low-Visibility Civic Engagement","description":"Community members and leaders who attempt to communicate or participate in public spaces face intense personal exposure with little transparency into how decisions or power actually operate. Because the risk of participation is high while structural clarity remains low, people self-censor, avoid public office, and disengage from dialogue.","x":4157,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_a168d595-bfad-40f1-9abb-1b65539b7c92","card_772bd853-8b69-42f2-b487-be7915a80117"]},{"@id":"card_d21df978-227c-4f7a-a017-7271f1d6c34f","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Fragmented Channels Fracture Shared Realities","description":"Election officials attempt to communicate across isolated media ecosystems, leaving different social groups to operate on mutually exclusive facts about distant jurisdictions.","x":3124,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_28","item_86c16dd7-803d-4de3-bb83-16ac8ccb93a3"]},{"@id":"card_dd102d6a-2751-433b-a2be-63d559284342","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Out-of-Jurisdiction Opacity Breeds Assumption of Bad Faith","description":"Because voters only see local election processes firsthand, the unfamiliar rules of distant jurisdictions appear mysterious—leading people to fill those information voids with suspicions of partisan cheating.","x":3238,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_d21df978-227c-4f7a-a017-7271f1d6c34f","card_48ac0422-747e-450c-ac9c-7c61b5007a00"]},{"@id":"card_e3fc7d36-c255-4121-8d3d-272513669640","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"The Illusion of Civic Agency","description":"Communities engage with public agencies expecting shared decision-making, only to find that institutional outputs remain insulated from their collective sentiment by legal and political barriers.","x":5436,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_09","item_14"]},{"@id":"card_ff76f358-8e85-47fc-9930-62569095b2db","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"","description":"","x":7448,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_24","item_ac4140f1-032a-4ed8-974d-e7a74c5dd4fe"]},{"@id":"card_b588c655-88c6-4921-83d7-87122ab43698","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Private Isolation from Collapsed Civic Scaffolding","description":"Local residents struggle to form community ties because historic relational structures have vanished, forcing individuals to shoulder what was once a shared civic responsibility.","x":7112,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_ac4140f1-032a-4ed8-974d-e7a74c5dd4fe","item_24"]},{"@id":"card_22c29d8d-32d9-4ae4-80c4-03f07f0d27b5","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Lack of local small organization engagement","description":"Overwhelmed board members default to legacy paper and spreadsheet routines, accidentally locking out broader member participation through administrative friction","x":6776,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_25","item_ac4140f1-032a-4ed8-974d-e7a74c5dd4fe"]},{"@id":"card_4160a068-8c0b-4414-9633-eb9b0dd3dba9","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"disconect of people at local level","description":"","x":6934,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_22c29d8d-32d9-4ae4-80c4-03f07f0d27b5","card_b588c655-88c6-4921-83d7-87122ab43698"]},{"@id":"card_64dbc21b-9797-4f05-9200-0f41afb68003","@type":"tg:Theme","type":"Theme","tier":3,"title":"Structural Opacity Converts Distance Into Threat","description":"When citizens cannot see how decisions, timelines, or out-of-jurisdiction elections actually operate, they fill the structural void with assumptions of malice, while those facing public exposure self-censor to protect themselves. This transforms routine civic friction into an unmanageable personal risk and widespread institutional distrust.","x":3651.890283050769,"y":-844.9173926334397,"w":340,"h":150,"cardType":null,"locked":false,"children":["card_4f8e239a-3235-42f3-bccf-78df947d901a","card_dd102d6a-2751-433b-a2be-63d559284342"]},{"@id":"card_e8abcc80-94ad-4269-b4f7-bbe17ddd6bd3","@type":"tg:Theme","type":"Theme","tier":3,"title":"Algorithms and clickbait expanding distrust","description":"","x":2665,"y":-840,"w":340,"h":150,"cardType":null,"locked":false,"children":["card_dc734b4d-8db7-416e-9121-9ba49bd3d989","card_dd102d6a-2751-433b-a2be-63d559284342"]},{"@id":"card_59f29353-ee7b-4f7a-b135-aecf4b47e8a4","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Distrust and Disinformation with social media","description":"","x":772,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_10","item_15"]},{"@id":"card_e82b7747-33b6-456c-b5e9-43de573fd1fc","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Accountability","description":"","x":7896,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_46","item_43"]},{"@id":"card_b273d6d5-6790-497d-bffc-d4eb9230f47c","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"finding localized community engagement opportunities","description":"","x":6440,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_48","item_ac4140f1-032a-4ed8-974d-e7a74c5dd4fe"]},{"@id":"card_57395264-69ec-4865-a9cb-f2fe29c434dd","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Unclear election rules","description":"The impacts of election processes are opaque for citizens. ","x":9172,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_22","item_04","item_39"]},{"@id":"card_39db5838-c166-4308-af79-f9c9f1724361","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Equity of representation","description":"System designers and incumbent gatekeepers operate rules that freeze demographic power balances before ballots are cast. As a result, non-dominant groups waste agency trying to win within a rigged spatial and institutional architecture.","x":10448,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_558a3c99-862d-45c1-b33a-e95fcef51102","item_40"]},{"@id":"card_1732d47d-6e13-4cae-a883-2e60395c40e2","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Misinformation across groups","description":"","x":2788,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_02","item_86c16dd7-803d-4de3-bb83-16ac8ccb93a3"]},{"@id":"card_5550f526-868b-4726-ab72-2f18e7798249","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Campaign finance and overrepresented voices","description":"Everyday voters lose meaningful representation because concentrated spending and boundary manipulation neutralize competitive elections before ballots are cast.","x":5772,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_09","item_03"]},{"@id":"card_f2bcd866-e50c-4cae-9ff9-85cf4001a7c1","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Unclear voting processes","description":"Challenge of educating voters quickly and efficiently on voting and electoral issues","x":8836,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_11","item_22"]},{"@id":"card_3082d8cd-7de3-438e-b4e7-94437b9632e9","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Genuine dialogue eaten by clickbait","description":"Civic institutions attempt to reach community members through open communication channels, but automated spam and competing entertainment options exhaust citizen attention and obscure genuine dialogue.","x":1108,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_37","item_15"]},{"@id":"card_a41c5011-9bf3-4622-829a-e4a4f86766d0","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Ranked voting challenges","description":"Voters face complex new choice architectures while election bodies and civic media fail to deliver clear, accessible candidate information. As a result, voters experience decision paralysis or default to low-information voting, blunting the intended systemic benefits of reform.","x":9508,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_34","item_04"]},{"@id":"card_fb0e04c2-46f6-40f2-be26-b648f7f43184","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Gerrymandering","description":"","x":3796,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_17","item_33"]},{"@id":"card_878fada5-7858-47c0-a158-c89284601669","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Participation apathy","description":"Voters recognize that traditional turnout mechanisms yield negligible structural change, resulting in deliberate, rational non-participation.","x":10784,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_35","item_5736cc04-fae6-40f2-93f5-6ecd32be8bd3"]},{"@id":"card_00c38b08-06f9-4534-a43e-204b95f77f3b","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Local coordination of resources","description":"Government agencies and service providers isolate their funding and authority, leaving unpaid local leaders and constituents to manually bridge the gap between existing resources and community awareness.","x":12133,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_47","item_44"]},{"@id":"card_b17adcaf-7de5-477d-9b18-d7c37febe8ee","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Local constituent services operational challenges","description":"High-barrier navigation processes and templated political communications wall off available public resources from the constituents who need them most.","x":11797,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_47","item_36"]},{"@id":"card_5e9d8b92-8c8b-458a-8ec1-5f0151378cd7","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Local level Resource Coordination communication challenges` ","description":"","x":12090,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_b17adcaf-7de5-477d-9b18-d7c37febe8ee","card_00c38b08-06f9-4534-a43e-204b95f77f3b"]},{"@id":"card_5e48b6db-6b12-4952-8a62-44304be9bd29","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Civic Mandates Without Functional Literacy","description":"The state demands active civic participation through voting while systematically failing to provide the basic structural education required to make informed choices. This disconnect shifts the burden of interpretation entirely onto individual citizens, turning the ballot box into an exercise in guesswork.","x":8940,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_f2bcd866-e50c-4cae-9ff9-85cf4001a7c1","card_57395264-69ec-4865-a9cb-f2fe29c434dd"]},{"@id":"card_6d7ccc61-6b68-435e-908a-a0d1a4a227ff","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Procedural Reform Disconnected From Voter Literacy","description":"Institutional changes to how people vote outpace public education regarding what offices do and how new voting rules operate. Consequently, the intended systemic benefits of election reforms are blunted because voters cannot reliably connect their intent to the mechanism on the page.","x":9384,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_57395264-69ec-4865-a9cb-f2fe29c434dd","card_a41c5011-9bf3-4622-829a-e4a4f86766d0"]},{"@id":"card_4bc3cfae-dd07-4fc8-955e-6b8490b6269f","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"1. Rational Withdrawal From Rigged Architecture","description":"Non-dominant voters recognize that institutional gatekeepers use fixed structural rules to pre-determine power balances, turning deliberate non-participation into a logical response to invisible glass ceilings.","x":10606,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_39db5838-c166-4308-af79-f9c9f1724361","card_878fada5-7858-47c0-a158-c89284601669"]},{"@id":"card_0799bb67-6159-4d7a-8e3d-a602b57e1e9e","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Pre-Empted Democratic Outcomes ","description":"Structural barriers like gerrymandered boundaries and legal precedents neutralize citizen input long before votes or public comments are registered.","x":5436,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_e3fc7d36-c255-4121-8d3d-272513669640","card_5550f526-868b-4726-ab72-2f18e7798249"]},{"@id":"card_3f18aaf3-53c5-4afe-881c-fd8ccae76f5f","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Information Lack","description":"The public lacks the civic literacy — not the access — to convert available political information into actions that move policy; information sits in reach but inert, because using it requires interpretive and procedural skills most citizens don't have and no one is responsible for building.","x":12818,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_13da2d54-a4f9-48f5-8326-125c3eab8afd","item_a85dd0dd-2a9a-4f82-990b-9513ccd27b29"]},{"@id":"card_29794a5b-448d-4505-a503-c2f45a61d942","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Information Determination","description":"The public relies on a functioning shortcut — deferring to experts/authorities — to judge policy claims that exceed most people's direct domain literacy. That shortcut fails at the population level whenever authorities visibly disagree or compete for confidence, and it's currently unclear whether the failure is because most people lack the literacy to adjudicate independently, or because the contexts in which claims reach them (soundbites, debates, compressed news cycles) strip out what even literate people would need to adjudicate — or because disagreement gets resolved by identity/motivated reasoning rather than either literacy or context.","x":12482,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_a85dd0dd-2a9a-4f82-990b-9513ccd27b29","item_5d50f77c-901a-43de-811f-e4709ba6c4f3"]},{"@id":"card_3e43a493-2988-4773-901b-1fb9e3ea992b","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Information Overload","description":"There is no shared civic infrastructure — no common source, venue, or channel — where local political information circulates. Both signals point to an absence of a shared informational commons at the local level: national/federal information crowds out local, and there's no common space where local facts would even live if someone looked for them.","x":13154,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_a85dd0dd-2a9a-4f82-990b-9513ccd27b29","item_d0b5d166-5503-418c-98f1-50d05b2cf460"]},{"@id":"card_0f3b468a-123f-46b4-935d-c7ac932750ec","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"What do I wan to say?","description":"People are exposed to information but lack a reliable way to convert it into a defensible opinion — the friction isn't that information is missing, it's that turning available information into a judgment requires either a skill (literacy) or a trustworthy shortcut (deference to experts), and both are unreliable under real conditions.","x":12845,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_3f18aaf3-53c5-4afe-881c-fd8ccae76f5f","card_29794a5b-448d-4505-a503-c2f45a61d942","card_3e43a493-2988-4773-901b-1fb9e3ea992b"]},{"@id":"card_115ff78b-d5d2-4d39-8c93-72b0da40f3ef","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Local better?","description":"Before any civic action happens, a person has to judge whether it's \"worth it\" — and something is currently blocking that judgment from being made, whether the blockage is a resource constraint (time), an information gap (what the action would actually accomplish locally), or both together. The mechanism is a stalled cost-benefit judgment, not yet a confirmed cause.","x":13490,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_b492e0a2-6e26-422c-8246-4d8bd7077e3a","item_dd50f501-2ac0-4d60-bd60-6f0d726e51d7"]},{"@id":"card_e5eeea22-864c-4c82-9408-aceacab78fad","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Why act?","description":"Citizens carry a rational-ignorance heuristic calibrated to federal-scale politics (\"my input won't change anything\") and apply it by default to local politics — where the actual effort-to-impact ratio is far more favorable — and nothing corrects this misapplication because no local information exists to show them their local leverage is different.","x":13826,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_dd50f501-2ac0-4d60-bd60-6f0d726e51d7","item_c5ed4538-18c1-4e16-8898-5d028a8e8398"]},{"@id":"card_be2bd9d7-b94f-4867-a68b-5c54114f30a1","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Who is responsible for feedback loops?","description":"Policymakers can act (or fail to act) on constituent opinion without any public record existing to verify whether they did — the accountability mechanism itself is invisible, because the data that would let anyone check \"did they listen\" is not made public.","x":14162,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_2d228eb1-0ec9-4702-bc3c-bed06ac2f8d2","item_dd50f501-2ac0-4d60-bd60-6f0d726e51d7"]},{"@id":"card_34b4c9c3-2051-49c9-95c6-3cf57312793c","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"I have an opinon- now what","description":"Across all three, there is no verifiable record connecting local civic input to local outcomes — neither citizens deciding whether to act, nor anyone checking whether officials responded, has access to evidence that effort at the local level actually produces effect. The recurring condition isn't \"no information\" broadly — it's specifically the absence of an outcome-verification link.","x":13723,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_e5eeea22-864c-4c82-9408-aceacab78fad","card_be2bd9d7-b94f-4867-a68b-5c54114f30a1","card_115ff78b-d5d2-4d39-8c93-72b0da40f3ef"]},{"@id":"card_b232d6b3-f50f-4983-bca8-9cfafecfc013","@type":"tg:Theme","type":"Theme","tier":3,"title":"What to say- and where to say it","description":"Underneath both patterns is the same unmet human need: people need to see a causal line between their own action and a consequence in the world in order to believe the action is worth taking — and at the local political scale, no infrastructure exists, on either end, to make that causal line visible. The front-end patterns fails to supply \"what would matter,\" the back-end pattern fails to supply \"did it matter\" — leaving the basic human requirement for legible efficacy structurally unmet, not because people lack the will to act, but because the system provides no evidence either direction.","x":13264,"y":-840,"w":340,"h":150,"cardType":null,"locked":false,"children":["card_0f3b468a-123f-46b4-935d-c7ac932750ec","card_34b4c9c3-2051-49c9-95c6-3cf57312793c"]},{"@id":"card_5d623537-cd31-4615-8052-b15ae39cf888","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Procedural Friction Triggers Civic Withdrawal","description":"Voters facing convoluted voting mechanics, such as ranked-choice rules, and a polluted information environment opt out of participating rather than navigate a system they cannot decode.","x":15596,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_5e251afb-9e99-49b1-a4f7-b96ff10657f7","item_c5a4bf8a-1714-4719-ac31-fe1b72fa3a78"]},{"@id":"card_e9d1ca0e-7a9a-4841-aa1b-9ef317db396d","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Implementation Outpaces Educational Scaffolding","description":"When administrators deploy new ranked-choice voting structures without providing sufficient public education or unbiased candidate data, voters are left confused by the mechanics and unable to adapt their voting behavior.","x":15932,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_c5a4bf8a-1714-4719-ac31-fe1b72fa3a78","item_0aa0041a-a5ba-4a39-8ce0-d20702537235"]},{"@id":"card_627b5834-44ba-4da7-a1a7-2f9cb89fb85b","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Unscaffolded Reform Drives Voter Withdrawal","description":"When administrators introduce complex new voting mechanics without providing the necessary educational support or neutral candidate data, the resulting cognitive burden causes voters to simply abandon the process.","x":15596,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_5d623537-cd31-4615-8052-b15ae39cf888","card_e9d1ca0e-7a9a-4841-aa1b-9ef317db396d"]},{"@id":"card_f8e2261e-2a55-4617-808d-6c1e309debd4","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Disinformation Exploits Baseline Civic Confusion","description":"Political entities use internet-era disinformation to weaponize voters' lack of procedural literacy, leading impacted populations to either withdraw completely or succumb to manipulated instincts.","x":15260,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_5e251afb-9e99-49b1-a4f7-b96ff10657f7","item_986fd3d2-f54b-44ab-89ef-3beb4a18135e"]},{"@id":"card_90cfcde9-9a3a-444a-b17c-3d9db24eea03","@type":"tg:Evidence","type":"Evidence","tier":1,"title":"Local Information Deserts Invite Manipulation","description":"The systemic absence of actionable local candidate data creates an information vacuum, forcing voters to rely on superficial cues like yard signs while leaving them highly vulnerable to targeted disinformation.","x":14924,"y":-280,"w":280,"h":150,"cardType":null,"locked":false,"children":["item_a684b0d7-d40a-4ed9-a403-d1f5d0a779a2","item_986fd3d2-f54b-44ab-89ef-3beb4a18135e"]},{"@id":"card_d9f823d2-a6b5-4b99-a777-b95f18965b88","@type":"tg:Pattern","type":"Pattern","tier":2,"title":"Civic Voids Invite Weaponized Noise","description":"When systemic failures create local information deserts and procedural confusion, bad actors flood the gap with disinformation, causing voters to either withdraw entirely or fall prey to manipulation.","x":15240,"y":-560,"w":300,"h":150,"cardType":null,"locked":false,"children":["card_90cfcde9-9a3a-444a-b17c-3d9db24eea03","card_f8e2261e-2a55-4617-808d-6c1e309debd4"]},{"@id":"card_92764860-d149-4de1-81f1-9dc199c979c1","@type":"tg:Theme","type":"Theme","tier":3,"title":"Unusable Civic Systems Exhaust Voter Bandwidth","description":"When the state designs electoral mechanics and information environments that demand excessive cognitive labor, everyday citizens cannot decode the process and are forced to abandon their political agency.","x":15398,"y":-840,"w":340,"h":150,"cardType":null,"locked":false,"children":["card_d9f823d2-a6b5-4b99-a777-b95f18965b88","card_627b5834-44ba-4da7-a1a7-2f9cb89fb85b"]},{"@id":"card_a2ce2581-4de7-457b-8f8f-4f6b79a7e90f","@type":"tg:Theme","type":"Theme","tier":3,"title":"","description":"","x":12421.028798052253,"y":-909.6228632029373,"w":340,"h":150,"cardType":null,"locked":true,"children":["card_0f3b468a-123f-46b4-935d-c7ac932750ec","card_5e9d8b92-8c8b-458a-8ec1-5f0151378cd7"]}]},"extractsCsv":"title,summary,source_url,verified\nTruths / Facts,are not shared across groups,,true\nAccess to information,about local candidate records is not easy to find (self-reported),,true\nFinding hyper-local,community engagement is hard,,true\nOrganizing individual volunteers,is a labor intensive process w/ lots of attrition,,true\nEquality of representation,gerrymandering voters are not equally represented,,true\nParticipation apathy,voter turnout is low,,true\nRestructuring the Political System,A high-level desire to shift the fundamental political structure of the United States to model other international systems.,https://theupskillinglabs.org/survey/civics/results#r-1,false\nMedia Misinformation,Broad concerns regarding how misleading media and digital influencing are negatively impacting civic engagement.,https://theupskillinglabs.org/survey/civics/results#r-3,false\nCampaign Finance & District Competitiveness,Observations that financial influence and gerrymandering have reduced the competitiveness of congressional districts.,https://theupskillinglabs.org/survey/civics/results#r-4,false\nRanked Choice Voting Education,The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.,https://theupskillinglabs.org/survey/civics/results#r-5,false\nTargeting Legislative Influence,It is currently too labor-intensive and expensive to identify the most effective individuals or groups to lobby specific legislators on specific issues at the right time.,https://theupskillinglabs.org/survey/civics/results#r-6,false\nLocal Candidate Information Gaps,\"Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\",https://theupskillinglabs.org/survey/civics/results#r-7,false\nPublic Engagement on Government AI,Citizens lack the tools and platforms to provide feedback on or inform how government agencies and companies deploy artificial intelligence in their communities.,https://theupskillinglabs.org/survey/civics/results#r-8,false\nRecycling Contamination & Civic Decay,\"Improper recycling in public spaces leads to systemic waste and creates a visible, self-perpetuating belief that responsible civic behavior doesn't matter.\",https://theupskillinglabs.org/survey/civics/results#r-9,false\nCampaign Finance,Reform efforts consistently hit roadblocks like the Citizens United decision.,https://theupskillinglabs.org/survey/civics/results#r-10,false\nCivic Distrust & Disinformation,\"A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\",https://theupskillinglabs.org/survey/civics/results#r-11,false\nLogistical & Educational Barriers to Voting,\"Voting is burdened by physical hurdles (childcare, time off work) and a lack of plain-language education on how local elections directly impact citizens' daily lives.\",https://theupskillinglabs.org/survey/civics/results#r-12,false\nThe Death of Political Compromise,\"The electorate and activists are failing to recognize that compromise is a fundamental component of democracy, negatively impacting civic engagement.\",https://theupskillinglabs.org/survey/civics/results#r-13,false\nCivics Talent Pipeline Shortage,There is a noticeable shortage of talent to fill junior roles within the civics and elections workforce.,https://theupskillinglabs.org/survey/civics/results#r-14,false\nFalse Transparency in Government,\"Government agencies and schools exhibit a disconnect with their constituencies, presenting a 'false flag' of transparency that leaves communities feeling ignored without understanding how aggregate sentiment is utilized.\",https://theupskillinglabs.org/survey/civics/results#r-15,false\nAI Bot Interference in Constituent Engagement,\"Artificial intelligence is being used to flood communication channels, rendering actual, organic constituent engagement ineffective.\",https://theupskillinglabs.org/survey/civics/results#r-16,false\nHopelessness & Lack of Election Information,\"Voters feel hopeless and lack basic awareness of when local elections occur, relying on passive information like mailers or word of mouth.\",https://theupskillinglabs.org/survey/civics/results#r-17,false\nStructural Election Imbalances,\"The current electoral system features gerrymandering, dominant two-party privileges, and districts so large that politicians effectively choose their voters.\",https://theupskillinglabs.org/survey/civics/results#r-18,false\nPolitical Bubbles & NIMBYism,\"Citizens are highly polarized and isolated in social bubbles, proposing solutions or pushing back on reforms without understanding the broader impacts, trade-offs, or equity implications beyond their circles.\",https://theupskillinglabs.org/survey/civics/results#r-19,false\nVolunteer Burnout & Knowledge Transfer,\"Local volunteer roles, such as PTA leadership, fall on a few individuals. There is a need for tools to reduce the operational burden and retain institutional knowledge as volunteer leadership turns over.\",https://theupskillinglabs.org/survey/civics/results#r-19,false\nAging Civic Leadership,\"Local civic organizations are heavily reliant on aging populations for leadership and membership, struggling to recruit younger generations who face competing career and family priorities.\",https://theupskillinglabs.org/survey/civics/results#r-20,false\nUncontested Local Candidate Transparency,\"It is incredibly difficult to research the records of local election candidates, especially those running uncontested or without a communications budget, leaving voters feeling uninformed.\",https://theupskillinglabs.org/survey/civics/results#r-21,false\nUnexplained Ballot Roles,\"Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.\",https://theupskillinglabs.org/survey/civics/results#r-22,false\nPerformative Bipartisanship,\"Statements, town halls, and pledges perform collaboration without doing it; missing is a structured, sprint-like way for people who are supposed to disagree to define a shared problem and build something together.\",https://theupskillinglabs.org/survey/civics/results#r-23,false\nLoneliness as a Civic Problem,The social scaffolding that once created accountability in how people form relationships has dissolved with nothing replacing it — an isolation epidemic treated as a private matter rather than missing civic infrastructure.,https://theupskillinglabs.org/survey/civics/results#r-24,false\nOutdated Small-Organization Elections,\"Unions, HOAs, and nonprofit boards run consequential elections on paper ballots and opaque spreadsheets; available tools serve incumbent leadership rather than transparent, verifiable results for members.\",https://theupskillinglabs.org/survey/civics/results#r-25,false\nEroded Respect for Disagreement,\"People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.\",https://theupskillinglabs.org/survey/civics/results#r-26,false\nMisunderstood Pace of Government,\"Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.\",https://theupskillinglabs.org/survey/civics/results#r-27,false\nCross-Jurisdiction Election Distrust,\"Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\",https://theupskillinglabs.org/survey/civics/results#r-28,false\nNo Playbook for Good Citizenship,\"There is no clear guide to the daily, weekly, and monthly steps of being an informed, participating citizen — the information is scattered everywhere, and the whole project feels overwhelming.\",https://theupskillinglabs.org/survey/civics/results#r-29,false\nBroad Civic Disengagement,\"Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.\",https://theupskillinglabs.org/survey/civics/results#r-30,false\nMissing Dialogue Across Difference,\"People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.\",https://theupskillinglabs.org/survey/civics/results#r-31,false\nUntapped Personal Megaphones,People forget how influential they can be with the biggest megaphone in history in the palm of their hand — but no one has cracked engagement at scale without it devolving into a rage machine.,https://theupskillinglabs.org/survey/civics/results#r-32,false\nLow-Information Voting & Gerrymandering,\"Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.\",https://theupskillinglabs.org/survey/civics/results#r-33,false\nRanked-Choice Confusion Persists,\"Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\",https://theupskillinglabs.org/survey/civics/results#r-34,false\n\"Anemic, Uneven Participation\",\"Civic participation is thin, and only some voices get heard and lifted.\",https://theupskillinglabs.org/survey/civics/results#r-35,false\nConstituent Mail Black Hole,\"Letters and emails to representatives feel like talking into a void — heartfelt messages come back as generic, strategist-polished boilerplate.\",https://theupskillinglabs.org/survey/civics/results#r-36,false\nEntertainment Crowds Out Civic Attention,\"Citizens are too busy consuming entertainment to pay attention to neighborhood issues, kids' activities, or their government; outreach across multiple mediums still meets 'I don't have time'.\",https://theupskillinglabs.org/survey/civics/results#r-37,false\nComplacency & Candidate Deterrence,\"The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\",https://theupskillinglabs.org/survey/civics/results#r-38,false\nCalls for Stricter Ballot ID,A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.,https://theupskillinglabs.org/survey/civics/results#r-39,false\nWomen Still Under-Represented,\"Women remain under-represented in political leadership, even as women run for the highest offices.\",https://theupskillinglabs.org/survey/civics/results#r-40,false\nStudent Technology Access Gap,\"Students lack access to equipment for training, and school technology funding isn't keeping up; grassroots fundraisers and lobbying for federal funding only go so far.\",https://theupskillinglabs.org/survey/civics/results#r-41,false\nMid-Decade Redistricting Shifts,\"California, Missouri, North Carolina, and Texas will use different congressional maps in 2026 than in 2024 due to voluntary mid-decade redistricting — unusual, and worth watching for how it shifts competitive-district counts.\",https://theupskillinglabs.org/survey/civics/results#r-42,false\nAccountability for Public Lies,Telling the truth — and holding liars accountable and responsible — is named as the missing piece of civic life.,https://theupskillinglabs.org/survey/civics/results#r-43,false\nCross-Agency Coordination Failure,\"Constituent problems take years to solve because coordinating local, federal, and neighboring-state agencies, private entities, and residents is nearly impossible — stakeholders claim jurisdiction for credit and duck it for problem-solving, at great cost to unpaid commissioners.\",https://theupskillinglabs.org/survey/civics/results#r-44,false\nSidewalks vs. Micromobility,\"DC sidewalks are increasingly dangerous for elderly, young, and disabled pedestrians as motorized bikes and scooters — often ridden illegally — collide with the city's walkability promise; other cities' regulations may hold lessons.\",https://theupskillinglabs.org/survey/civics/results#r-45,false\nRepresentatives Without Accountability,\"Representatives don't seem to answer to the people, and replacing them changes little — new reps inherit the same voting patterns, with the two-party system and polarization at the crux.\",https://theupskillinglabs.org/survey/civics/results#r-46,false\nLast-Mile Resource Disconnect,\"Programs, grants, and services exist on paper, but communities often don't know about them or can't navigate them — the gap is grassroots outreach, trusted local partners, and hands-on navigation support, not new programs.\",https://theupskillinglabs.org/survey/civics/results#r-47,false\nCampus–Neighborhood Disconnection,\"There is no single, easy channel for a university community and its neighbors to trade information and opportunities — student jobs, local events, programs, and campus resources live in scattered slices.\",https://theupskillinglabs.org/survey/civics/results#r-48,false\nEconomist?,Generally officals and SMEs certainty even when problems/solutions are uncertain,,true\nVoter Turnout?,Declining or uneven participation rates across electorate demographics,,true\nRational ignorance,\"Individually rational to stay uninformed since one vote is rarely decisive, voting is a collective action problem\",,true\nElected officials make election policy,Convergence of Elected Officials and election policy,,true\nAccess to Engagement,Across demos,,true\nInformation Asymmetry?,Hard to find out about local elections; too much national/federal,,true\nLiteracy Rates,Baseline reading/civic literacy needed to navigate ballots and information,,true\nDemocratization of Public Opinion Data,Public opinion is essentials to hold policy makers accountable to constituents but the data is not public,,true\nShared Truth - or Spaces for Information,Lack of common spaces or sources for shared factual information,,true\nPublic Engagement,Public engagement is uneven or nonexistent particularly at the local level,,true\nLow Local Action,People don't have the time or information to determine what civic actions are 'worth it'.,,false\nMedia Misinformation,Broad concerns regarding how misleading media and digital influencing are negatively impacting civic engagement.,https://theupskillinglabs.org/survey/civics/results#r-3,false\nCampaign Finance & District Competitiveness,Observations that financial influence and gerrymandering have reduced the competitiveness of congressional districts.,https://theupskillinglabs.org/survey/civics/results#r-4,false\nRanked Choice Voting Education,The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.,https://theupskillinglabs.org/survey/civics/results#r-5,false\nTargeting Legislative Influence,It is currently too labor-intensive and expensive to identify the most effective individuals or groups to lobby specific legislators on specific issues at the right time.,https://theupskillinglabs.org/survey/civics/results#r-6,false\nLocal Candidate Information Gaps,\"Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\",https://theupskillinglabs.org/survey/civics/results#r-7,false\nPublic Engagement on Government AI,Citizens lack the tools and platforms to provide feedback on or inform how government agencies and companies deploy artificial intelligence in their communities.,https://theupskillinglabs.org/survey/civics/results#r-8,false\nCivic Distrust & Disinformation,\"A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\",https://theupskillinglabs.org/survey/civics/results#r-11,false\nLogistical & Educational Barriers to Voting,\"Voting is burdened by physical hurdles (childcare, time off work) and a lack of plain-language education on how local elections directly impact citizens' daily lives.\",https://theupskillinglabs.org/survey/civics/results#r-12,false\nThe Death of Political Compromise,\"The electorate and activists are failing to recognize that compromise is a fundamental component of democracy, negatively impacting civic engagement.\",https://theupskillinglabs.org/survey/civics/results#r-13,false\nCivics Talent Pipeline Shortage,There is a noticeable shortage of talent to fill junior roles within the civics and elections workforce.,https://theupskillinglabs.org/survey/civics/results#r-14,false\nFalse Transparency in Government,\"Government agencies and schools exhibit a disconnect with their constituencies, presenting a 'false flag' of transparency that leaves communities feeling ignored without understanding how aggregate sentiment is utilized.\",https://theupskillinglabs.org/survey/civics/results#r-15,false\nAI Bot Interference in Constituent Engagement,\"Artificial intelligence is being used to flood communication channels, rendering actual, organic constituent engagement ineffective.\",https://theupskillinglabs.org/survey/civics/results#r-16,false\nHopelessness & Lack of Election Information,\"Voters feel hopeless and lack basic awareness of when local elections occur, relying on passive information like mailers or word of mouth.\",https://theupskillinglabs.org/survey/civics/results#r-17,false\nStructural Election Imbalances,\"The current electoral system features gerrymandering, dominant two-party privileges, and districts so large that politicians effectively choose their voters.\",https://theupskillinglabs.org/survey/civics/results#r-18,false\nVolunteer Burnout & Knowledge Transfer,\"Local volunteer roles, such as PTA leadership, fall on a few individuals. There is a need for tools to reduce the operational burden and retain institutional knowledge as volunteer leadership turns over.\",https://theupskillinglabs.org/survey/civics/results#r-19,false\nAging Civic Leadership,\"Local civic organizations are heavily reliant on aging populations for leadership and membership, struggling to recruit younger generations who face competing career and family priorities.\",https://theupskillinglabs.org/survey/civics/results#r-20,false\nUncontested Local Candidate Transparency,\"It is incredibly difficult to research the records of local election candidates, especially those running uncontested or without a communications budget, leaving voters feeling uninformed.\",https://theupskillinglabs.org/survey/civics/results#r-21,false\nUnexplained Ballot Roles,\"Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.\",https://theupskillinglabs.org/survey/civics/results#r-22,false\nPerformative Bipartisanship,\"Statements, town halls, and pledges perform collaboration without doing it; missing is a structured, sprint-like way for people who are supposed to disagree to define a shared problem and build something together.\",https://theupskillinglabs.org/survey/civics/results#r-23,false\nLoneliness as a Civic Problem,The social scaffolding that once created accountability in how people form relationships has dissolved with nothing replacing it — an isolation epidemic treated as a private matter rather than missing civic infrastructure.,https://theupskillinglabs.org/survey/civics/results#r-24,false\nOutdated Small-Organization Elections,\"Unions, HOAs, and nonprofit boards run consequential elections on paper ballots and opaque spreadsheets; available tools serve incumbent leadership rather than transparent, verifiable results for members.\",https://theupskillinglabs.org/survey/civics/results#r-25,false\nEroded Respect for Disagreement,\"People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.\",https://theupskillinglabs.org/survey/civics/results#r-26,false\nMisunderstood Pace of Government,\"Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.\",https://theupskillinglabs.org/survey/civics/results#r-27,false\nCross-Jurisdiction Election Distrust,\"Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\",https://theupskillinglabs.org/survey/civics/results#r-28,false\nNo Playbook for Good Citizenship,\"There is no clear guide to the daily, weekly, and monthly steps of being an informed, participating citizen — the information is scattered everywhere, and the whole project feels overwhelming.\",https://theupskillinglabs.org/survey/civics/results#r-29,false\nBroad Civic Disengagement,\"Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.\",https://theupskillinglabs.org/survey/civics/results#r-30,false\nMissing Dialogue Across Difference,\"People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.\",https://theupskillinglabs.org/survey/civics/results#r-31,false\nLow-Information Voting & Gerrymandering,\"Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.\",https://theupskillinglabs.org/survey/civics/results#r-33,false\nRanked-Choice Confusion Persists,\"Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\",https://theupskillinglabs.org/survey/civics/results#r-34,false\n\"Anemic, Uneven Participation\",\"Civic participation is thin, and only some voices get heard and lifted.\",https://theupskillinglabs.org/survey/civics/results#r-35,false\nConstituent Mail Black Hole,\"Letters and emails to representatives feel like talking into a void — heartfelt messages come back as generic, strategist-polished boilerplate.\",https://theupskillinglabs.org/survey/civics/results#r-36,false\nEntertainment Crowds Out Civic Attention,\"Citizens are too busy consuming entertainment to pay attention to neighborhood issues, kids' activities, or their government; outreach across multiple mediums still meets 'I don't have time'.\",https://theupskillinglabs.org/survey/civics/results#r-37,false\nComplacency & Candidate Deterrence,\"The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\",https://theupskillinglabs.org/survey/civics/results#r-38,false\nCalls for Stricter Ballot ID,A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.,https://theupskillinglabs.org/survey/civics/results#r-39,false\nWomen Still Under-Represented,\"Women remain under-represented in political leadership, even as women run for the highest offices.\",https://theupskillinglabs.org/survey/civics/results#r-40,false\nStudent Technology Access Gap,\"Students lack access to equipment for training, and school technology funding isn't keeping up; grassroots fundraisers and lobbying for federal funding only go so far.\",https://theupskillinglabs.org/survey/civics/results#r-41,false\nMid-Decade Redistricting Shifts,\"California, Missouri, North Carolina, and Texas will use different congressional maps in 2026 than in 2024 due to voluntary mid-decade redistricting — unusual, and worth watching for how it shifts competitive-district counts.\",https://theupskillinglabs.org/survey/civics/results#r-42,false\nAccountability for Public Lies,Telling the truth — and holding liars accountable and responsible — is named as the missing piece of civic life.,https://theupskillinglabs.org/survey/civics/results#r-43,false\nCross-Agency Coordination Failure,\"Constituent problems take years to solve because coordinating local, federal, and neighboring-state agencies, private entities, and residents is nearly impossible — stakeholders claim jurisdiction for credit and duck it for problem-solving, at great cost to unpaid commissioners.\",https://theupskillinglabs.org/survey/civics/results#r-44,false\nRepresentatives Without Accountability,\"Representatives don't seem to answer to the people, and replacing them changes little — new reps inherit the same voting patterns, with the two-party system and polarization at the crux.\",https://theupskillinglabs.org/survey/civics/results#r-46,false\nLast-Mile Resource Disconnect,\"Programs, grants, and services exist on paper, but communities often don't know about them or can't navigate them — the gap is grassroots outreach, trusted local partners, and hands-on navigation support, not new programs.\",https://theupskillinglabs.org/survey/civics/results#r-47,false\nCampus–Neighborhood Disconnection,\"There is no single, easy channel for a university community and its neighbors to trade information and opportunities — student jobs, local events, programs, and campus resources live in scattered slices.\",https://theupskillinglabs.org/survey/civics/results#r-48,false\nvoter turnout,\"people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation\",,true\n","content":{"situation":"# Apathy - limited information about gov’t benefits\n\n> A problem situation mapped using Kees Dorst's Frame Creation method.\n> Built from 7 cards covering 7 signals across the evidence ladder.\n> Exported 2026-07-25T20:34:31.699Z.\n\n## The situation\nStructures and systems of how government works and benefits to me at a local level are not clear and so decentralized that people disengage from civic engagement. The gap of information about what the benefits are and who gets supported by those benefits turns into apathy or negative connotations.\n\n### Why this is open, not bounded\nIf you simplify local government public notices to increase participation, special interest groups will adapt their strategies to exploit those simplified channels.\n\nPeople's willingness to engage depends on personal bandwidth, culture, trust in media, and national political sentiment—factors completely outside the structure of local government itself.\n\n### Evidence trail\n• Theme: Structural Opacity Converts Distance Into Threat — When citizens cannot see how decisions, timelines, or out-of-jurisdiction elections actually operate, they fill the structural void with assumptions of malice, while those facing public exposure self-censor to protect themselves. This transforms routine civic friction into an unmanageable personal risk and widespread institutional distrust.\n  • Pattern: High-Risk, Low-Visibility Civic Engagement — Community members and leaders who attempt to communicate or participate in public spaces face intense personal exposure with little transparency into how decisions or power actually operate. Because the risk of participation is high while structural clarity remains low, people self-censor, avoid public office, and disengage from dialogue.\n    • Evidence: High-Risk, Low-Information Civic Spaces — Citizens and potential leaders experience local politics as an opaque, media-dominated environment, driving voter apathy and self-selection out of public leadership.\n      - Signal \"Local Candidate Information Gaps\": Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n      - Signal \"Complacency & Candidate Deterrence\": The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\n    • Evidence: Information Friction in Civic Power — Voters and stretched legislative staff operate without a shared baseline of who holds power and how fast it moves, causing civic outreach tools to fail at bridging the gap.\n      - Signal \"Broad Civic Disengagement\": Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.\n      - Signal \"Misunderstood Pace of Government\": Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.\n  • Pattern: Out-of-Jurisdiction Opacity Breeds Assumption of Bad Faith — Because voters only see local election processes firsthand, the unfamiliar rules of distant jurisdictions appear mysterious—leading people to fill those information voids with suspicions of partisan cheating.\n    • Evidence: Fragmented Channels Fracture Shared Realities — Election officials attempt to communicate across isolated media ecosystems, leaving different social groups to operate on mutually exclusive facts about distant jurisdictions.\n      - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n      - Signal \"Truths / Facts\": are not shared across groups\n    • Evidence: Structural Partisanship Distorts Electoral Legitimacy — Structural features like gerrymandering and voting rules reinforce partisan boundaries, causing voters to view routine out-of-jurisdiction election procedures through a lens of partisan threat.\n      - Signal \"Low-Information Voting & Gerrymandering\": Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.\n      - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n\n---\n\n## Evidence landscape\n### What the evidence covers\nStrong on problem, weak on players.\n\n### Gaps — what I think is still thin\nWhat information about which government benefits would engage people in getting involved civically? \nHow do people sort out the big picture understanding of government processes when they are opaque? \nWhere do people look for information and what information are they currently getting about government systems?\n\n---\n\n## Research access\n### Who I need to hear from\nDisengaged voters receiving government benefits\ndisengaged voters not receiving government benefits\ndisengaged citizens\n\n### What I can't reach alone — and how I might\ndatabase of non-voters\n\n---\n\n## The paradox\n\"The situation demands widespread local civic participation, but the same conditions that create the need—an opaque, fragmented local government structure—also prevent widespread local civic participation from working.\"\n\n_Sharpness self-check (pod-declared): 0/3._\n\n### Who benefits from the status quo\nHyper-Organized Special Interest Groups & NIMBYs\nIncumbent Politicians & Bureaucratic Leadership\nWell-Resourced Special Interests & Developers\n\n### How we know (evidence as warrant)\nNo client handed us this problem — the evidence did. This paradox was read off **7 source extracts** across **1 named theme** (Structural Opacity Converts Distance Into Threat). The full trail ships with this folder (`data/extracts.csv` + the themes narrative).\n\nRepresentative extracts:\n- \"Local Candidate Information Gaps\" — Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n- \"Complacency & Candidate Deterrence\" — The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\n\n### What we're still testing\n- What could break this framing: If you clearly showed someone how a local tax millage or zoning board decision affected their paycheck or neighborhood, they would care and take action. People are driven by self-interest and would act according to self interest. \n\nThe current dysfunction is caused by an absence of the general public and absence of shared information amongst the general public, rather than deep, irreconcilable conflicts within the public itself.\n- Sharpness still unclaimed: it names a contradiction where the fix undoes itself — x requires not-x\n- Sharpness still unclaimed: it names who is invested in it persisting\n- Sharpness still unclaimed: both legs of the contradiction are evidenced (linked cards / extracts)\n\n### Pressure-testing the framing\nIf you clearly showed someone how a local tax millage or zoning board decision affected their paycheck or neighborhood, they would care and take action. People are driven by self-interest and would act according to self interest. \n\nThe current dysfunction is caused by an absence of the general public and absence of shared information amongst the general public, rather than deep, irreconcilable conflicts within the public itself.\n\n---\n\n## The field — candidate problem owners\n(field not yet mapped — start with the inner circle, then widen, and mark who could own this)\n\n---\n\n## What comes next\nThis situation is mapped but not solved — and solving it is not the next step. The next steps in Frame Creation are:\n\n1. **Map the field** — identify every player connected to this situation or a future resolution. Define each by their practices and currency, not their title. Look especially for players who share the values your themes surfaced — even in distant, unexpected domains.\n2. **Identify a client** — from the potential problem owners, who could own this situation or adopt a resolution? What would they need to see?\n3. **Choose a delivery context** — through what kind of vehicle does a resolution reach the field? (An internal team, a government program, an open-source project, a startup, a nonprofit, a civic institution, a co-op — there is no right answer, only trade-offs.)\n4. **Deepen the archaeology** — the gaps above name what's still thin. Go find it: interview people, run deep-research sweeps, pull secondary sources.\n5. **Create frames** — only after the field is mapped and the archaeology is deep. \"If this situation is approached as if it is ___, then ___.\"\n","themes":"# Themes & Patterns\n\n## Theme: Structural Opacity Converts Distance Into Threat\nWhen citizens cannot see how decisions, timelines, or out-of-jurisdiction elections actually operate, they fill the structural void with assumptions of malice, while those facing public exposure self-censor to protect themselves. This transforms routine civic friction into an unmanageable personal risk and widespread institutional distrust.\n\n  • Pattern: High-Risk, Low-Visibility Civic Engagement — Community members and leaders who attempt to communicate or participate in public spaces face intense personal exposure with little transparency into how decisions or power actually operate. Because the risk of participation is high while structural clarity remains low, people self-censor, avoid public office, and disengage from dialogue.\n    • Evidence: High-Risk, Low-Information Civic Spaces — Citizens and potential leaders experience local politics as an opaque, media-dominated environment, driving voter apathy and self-selection out of public leadership.\n      - Signal \"Local Candidate Information Gaps\": Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n      - Signal \"Complacency & Candidate Deterrence\": The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\n    • Evidence: Information Friction in Civic Power — Voters and stretched legislative staff operate without a shared baseline of who holds power and how fast it moves, causing civic outreach tools to fail at bridging the gap.\n      - Signal \"Broad Civic Disengagement\": Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.\n      - Signal \"Misunderstood Pace of Government\": Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.\n  • Pattern: Out-of-Jurisdiction Opacity Breeds Assumption of Bad Faith — Because voters only see local election processes firsthand, the unfamiliar rules of distant jurisdictions appear mysterious—leading people to fill those information voids with suspicions of partisan cheating.\n    • Evidence: Fragmented Channels Fracture Shared Realities — Election officials attempt to communicate across isolated media ecosystems, leaving different social groups to operate on mutually exclusive facts about distant jurisdictions.\n      - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n      - Signal \"Truths / Facts\": are not shared across groups\n    • Evidence: Structural Partisanship Distorts Electoral Legitimacy — Structural features like gerrymandering and voting rules reinforce partisan boundaries, causing voters to view routine out-of-jurisdiction election procedures through a lens of partisan threat.\n      - Signal \"Low-Information Voting & Gerrymandering\": Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.\n      - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n\n## Theme: What to say- and where to say it\nUnderneath both patterns is the same unmet human need: people need to see a causal line between their own action and a consequence in the world in order to believe the action is worth taking — and at the local political scale, no infrastructure exists, on either end, to make that causal line visible. The front-end patterns fails to supply \"what would matter,\" the back-end pattern fails to supply \"did it matter\" — leaving the basic human requirement for legible efficacy structurally unmet, not because people lack the will to act, but because the system provides no evidence either direction.\n\n  • Pattern: What do I wan to say? — People are exposed to information but lack a reliable way to convert it into a defensible opinion — the friction isn't that information is missing, it's that turning available information into a judgment requires either a skill (literacy) or a trustworthy shortcut (deference to experts), and both are unreliable under real conditions.\n    • Evidence: Information Lack — The public lacks the civic literacy — not the access — to convert available political information into actions that move policy; information sits in reach but inert, because using it requires interpretive and procedural skills most citizens don't have and no one is responsible for building.\n      - Signal \"Literacy Rates\": Baseline reading/civic literacy needed to navigate ballots and information\n      - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n    • Evidence: Information Determination — The public relies on a functioning shortcut — deferring to experts/authorities — to judge policy claims that exceed most people's direct domain literacy. That shortcut fails at the population level whenever authorities visibly disagree or compete for confidence, and it's currently unclear whether the failure is because most people lack the literacy to adjudicate independently, or because the contexts in which claims reach them (soundbites, debates, compressed news cycles) strip out what even literate people would need to adjudicate — or because disagreement gets resolved by identity/motivated reasoning rather than either literacy or context.\n      - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n      - Signal \"Economist?\": Generally officals and SMEs certainty even when problems/solutions are uncertain\n    • Evidence: Information Overload — There is no shared civic infrastructure — no common source, venue, or channel — where local political information circulates. Both signals point to an absence of a shared informational commons at the local level: national/federal information crowds out local, and there's no common space where local facts would even live if someone looked for them.\n      - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n      - Signal \"Shared Truth - or Spaces for Information\": Lack of common spaces or sources for shared factual information\n  • Pattern: I have an opinon- now what — Across all three, there is no verifiable record connecting local civic input to local outcomes — neither citizens deciding whether to act, nor anyone checking whether officials responded, has access to evidence that effort at the local level actually produces effect. The recurring condition isn't \"no information\" broadly — it's specifically the absence of an outcome-verification link.\n    • Evidence: Why act? — Citizens carry a rational-ignorance heuristic calibrated to federal-scale politics (\"my input won't change anything\") and apply it by default to local politics — where the actual effort-to-impact ratio is far more favorable — and nothing corrects this misapplication because no local information exists to show them their local leverage is different.\n      - Signal \"Access to Engagement\": Across demos\n      - Signal \"Rational ignorance\": Individually rational to stay uninformed since one vote is rarely decisive, voting is a collective action problem\n    • Evidence: Who is responsible for feedback loops? — Policymakers can act (or fail to act) on constituent opinion without any public record existing to verify whether they did — the accountability mechanism itself is invisible, because the data that would let anyone check \"did they listen\" is not made public.\n      - Signal \"Democratization of Public Opinion Data\": Public opinion is essentials to hold policy makers accountable to constituents but the data is not public\n      - Signal \"Access to Engagement\": Across demos\n    • Evidence: Local better? — Before any civic action happens, a person has to judge whether it's \"worth it\" — and something is currently blocking that judgment from being made, whether the blockage is a resource constraint (time), an information gap (what the action would actually accomplish locally), or both together. The mechanism is a stalled cost-benefit judgment, not yet a confirmed cause.\n      - Signal \"Low Local Action\": People don't have the time or information to determine what civic actions are 'worth it'.\n      - Signal \"Access to Engagement\": Across demos\n\n## Theme: Unusable Civic Systems Exhaust Voter Bandwidth\nWhen the state designs electoral mechanics and information environments that demand excessive cognitive labor, everyday citizens cannot decode the process and are forced to abandon their political agency.\n\n  • Pattern: Civic Voids Invite Weaponized Noise — When systemic failures create local information deserts and procedural confusion, bad actors flood the gap with disinformation, causing voters to either withdraw entirely or fall prey to manipulation.\n    • Evidence: Local Information Deserts Invite Manipulation — The systemic absence of actionable local candidate data creates an information vacuum, forcing voters to rely on superficial cues like yard signs while leaving them highly vulnerable to targeted disinformation.\n      - Signal \"Local Candidate Information Gaps\": Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n      - Signal \"Civic Distrust & Disinformation\": A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\n    • Evidence: Disinformation Exploits Baseline Civic Confusion — Political entities use internet-era disinformation to weaponize voters' lack of procedural literacy, leading impacted populations to either withdraw completely or succumb to manipulated instincts.\n      - Signal \"voter turnout\": people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation\n      - Signal \"Civic Distrust & Disinformation\": A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\n  • Pattern: Unscaffolded Reform Drives Voter Withdrawal — When administrators introduce complex new voting mechanics without providing the necessary educational support or neutral candidate data, the resulting cognitive burden causes voters to simply abandon the process.\n    • Evidence: Procedural Friction Triggers Civic Withdrawal — Voters facing convoluted voting mechanics, such as ranked-choice rules, and a polluted information environment opt out of participating rather than navigate a system they cannot decode.\n      - Signal \"voter turnout\": people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation\n      - Signal \"Ranked-Choice Confusion Persists\": Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\n    • Evidence: Implementation Outpaces Educational Scaffolding — When administrators deploy new ranked-choice voting structures without providing sufficient public education or unbiased candidate data, voters are left confused by the mechanics and unable to adapt their voting behavior.\n      - Signal \"Ranked-Choice Confusion Persists\": Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\n      - Signal \"Ranked Choice Voting Education\": The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.\n\n## Pattern: Algorithmic Disruption Accelerating Stakeholder Exhaustion\nPolarized constituents attempting cross-ideological dialogue face automated channel flooding alongside social hostility, driving them to abandon shared civic spaces entirely.\n\n  • Evidence: Exhaustion of Cross-Ideological Tolerance — Local stakeholders disengage from ideological opponents because active listening has vanished from public forums, rendering current participation tools largely ineffective.\n    - Signal \"Eroded Respect for Disagreement\": People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.\n    - Signal \"Missing Dialogue Across Difference\": People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.\n  • Evidence: Digital Channels Alienating Polarized Constituents — Differing political groups encounter AI-generated interference whenever they attempt online dialogue, driving them away from shared digital spaces. Consequently, new civic engagement tools only exacerbate isolation rather than bridging differences.\n    - Signal \"AI Bot Interference in Constituent Engagement\": Artificial intelligence is being used to flood communication channels, rendering actual, organic constituent engagement ineffective.\n    - Signal \"Missing Dialogue Across Difference\": People who hold differing views about a topic rarely talk with each other; new civic-engagement software is being tried, with only some success.\n  • Evidence: Passive Awareness Meets Active Polarization — Disengaged voters rely on passive, opportunistic information channels to learn about local elections while experiencing a civic culture that no longer tolerates ideological disagreement. As a result, alienation deepens into a total retreat from local democratic participation.\n    - Signal \"Hopelessness & Lack of Election Information\": Voters feel hopeless and lack basic awareness of when local elections occur, relying on passive information like mailers or word of mouth.\n    - Signal \"Eroded Respect for Disagreement\": People can no longer agree to disagree — basic respect for others and their opinions is missing from civic life, and active listening is rare.\n\n## Pattern: High-Risk, Low-Visibility Civic Engagement\nCommunity members and leaders who attempt to communicate or participate in public spaces face intense personal exposure with little transparency into how decisions or power actually operate. Because the risk of participation is high while structural clarity remains low, people self-censor, avoid public office, and disengage from dialogue.\n\n  • Evidence: High-Risk, Low-Information Civic Spaces — Citizens and potential leaders experience local politics as an opaque, media-dominated environment, driving voter apathy and self-selection out of public leadership.\n    - Signal \"Local Candidate Information Gaps\": Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n    - Signal \"Complacency & Candidate Deterrence\": The average citizen doesn't feel they can make a difference, and good people stay away from political office because media can form any narrative it wants about them.\n  • Evidence: Information Friction in Civic Power — Voters and stretched legislative staff operate without a shared baseline of who holds power and how fast it moves, causing civic outreach tools to fail at bridging the gap.\n    - Signal \"Broad Civic Disengagement\": Many people are not engaged in local or national politics, don't know who the candidates are or what they stand for, and don't vote — despite candidate forums and get-out-the-vote efforts.\n    - Signal \"Misunderstood Pace of Government\": Constituents misjudge who holds which powers and how fast government was designed to move, so legitimate slowness reads as failure — and stretched congressional staff can't give every issue the weight visitors expect.\n\n## Pattern: Out-of-Jurisdiction Opacity Breeds Assumption of Bad Faith\nBecause voters only see local election processes firsthand, the unfamiliar rules of distant jurisdictions appear mysterious—leading people to fill those information voids with suspicions of partisan cheating.\n\n  • Evidence: Fragmented Channels Fracture Shared Realities — Election officials attempt to communicate across isolated media ecosystems, leaving different social groups to operate on mutually exclusive facts about distant jurisdictions.\n    - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n    - Signal \"Truths / Facts\": are not shared across groups\n  • Evidence: Structural Partisanship Distorts Electoral Legitimacy — Structural features like gerrymandering and voting rules reinforce partisan boundaries, causing voters to view routine out-of-jurisdiction election procedures through a lens of partisan threat.\n    - Signal \"Low-Information Voting & Gerrymandering\": Many voters don't research candidates before an election, while nationwide gerrymandering and proposed federal voting restrictions make the underlying playing field less fair.\n    - Signal \"Cross-Jurisdiction Election Distrust\": Election officials struggle to cut through fragmented information channels, and even people who trust their own town's elections increasingly distrust elections run by other cities and states.\n\n## Pattern: Civic Mandates Without Functional Literacy\nThe state demands active civic participation through voting while systematically failing to provide the basic structural education required to make informed choices. This disconnect shifts the burden of interpretation entirely onto individual citizens, turning the ballot box into an exercise in guesswork.\n\n  • Evidence: Unclear voting processes — Challenge of educating voters quickly and efficiently on voting and electoral issues\n    - Signal \"Logistical & Educational Barriers to Voting\": Voting is burdened by physical hurdles (childcare, time off work) and a lack of plain-language education on how local elections directly impact citizens' daily lives.\n    - Signal \"Unexplained Ballot Roles\": Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.\n  • Evidence: Unclear election rules — The impacts of election processes are opaque for citizens. \n    - Signal \"Unexplained Ballot Roles\": Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.\n    - Signal \"Ranked Choice Voting Education\": The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.\n    - Signal \"Calls for Stricter Ballot ID\": A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.\n\n## Pattern: Procedural Reform Disconnected From Voter Literacy\nInstitutional changes to how people vote outpace public education regarding what offices do and how new voting rules operate. Consequently, the intended systemic benefits of election reforms are blunted because voters cannot reliably connect their intent to the mechanism on the page.\n\n  • Evidence: Unclear election rules — The impacts of election processes are opaque for citizens. \n    - Signal \"Unexplained Ballot Roles\": Even where ranked-choice mechanics were well taught, voters lack a plain-language breakdown of what each office on the ballot actually does, leaving first-time voters guessing at the roles they're electing.\n    - Signal \"Ranked Choice Voting Education\": The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.\n    - Signal \"Calls for Stricter Ballot ID\": A demand that in-person voting require Real ID and that mail-in ballots require verified identification — described by the submitter as widely supported yet repeatedly rejected.\n  • Evidence: Ranked voting challenges — Voters face complex new choice architectures while election bodies and civic media fail to deliver clear, accessible candidate information. As a result, voters experience decision paralysis or default to low-information voting, blunting the intended systemic benefits of reform.\n    - Signal \"Ranked-Choice Confusion Persists\": Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\n    - Signal \"Ranked Choice Voting Education\": The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.\n\n## Pattern: 1. Rational Withdrawal From Rigged Architecture\nNon-dominant voters recognize that institutional gatekeepers use fixed structural rules to pre-determine power balances, turning deliberate non-participation into a logical response to invisible glass ceilings.\n\n  • Evidence: Equity of representation — System designers and incumbent gatekeepers operate rules that freeze demographic power balances before ballots are cast. As a result, non-dominant groups waste agency trying to win within a rigged spatial and institutional architecture.\n    - Signal \"Equality of representation\": gerrymandering voters are not equally represented\n    - Signal \"Women Still Under-Represented\": Women remain under-represented in political leadership, even as women run for the highest offices.\n  • Evidence: Participation apathy — Voters recognize that traditional turnout mechanisms yield negligible structural change, resulting in deliberate, rational non-participation.\n    - Signal \"Anemic, Uneven Participation\": Civic participation is thin, and only some voices get heard and lifted.\n    - Signal \"Participation apathy\": voter turnout is low\n\n## Pattern: Pre-Empted Democratic Outcomes \nStructural barriers like gerrymandered boundaries and legal precedents neutralize citizen input long before votes or public comments are registered.\n\n  • Evidence: The Illusion of Civic Agency — Communities engage with public agencies expecting shared decision-making, only to find that institutional outputs remain insulated from their collective sentiment by legal and political barriers.\n    - Signal \"Campaign Finance\": Reform efforts consistently hit roadblocks like the Citizens United decision.\n    - Signal \"False Transparency in Government\": Government agencies and schools exhibit a disconnect with their constituencies, presenting a 'false flag' of transparency that leaves communities feeling ignored without understanding how aggregate sentiment is utilized.\n  • Evidence: Campaign finance and overrepresented voices — Everyday voters lose meaningful representation because concentrated spending and boundary manipulation neutralize competitive elections before ballots are cast.\n    - Signal \"Campaign Finance\": Reform efforts consistently hit roadblocks like the Citizens United decision.\n    - Signal \"Campaign Finance & District Competitiveness\": Observations that financial influence and gerrymandering have reduced the competitiveness of congressional districts.\n\n## Pattern: What do I wan to say?\nPeople are exposed to information but lack a reliable way to convert it into a defensible opinion — the friction isn't that information is missing, it's that turning available information into a judgment requires either a skill (literacy) or a trustworthy shortcut (deference to experts), and both are unreliable under real conditions.\n\n  • Evidence: Information Lack — The public lacks the civic literacy — not the access — to convert available political information into actions that move policy; information sits in reach but inert, because using it requires interpretive and procedural skills most citizens don't have and no one is responsible for building.\n    - Signal \"Literacy Rates\": Baseline reading/civic literacy needed to navigate ballots and information\n    - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n  • Evidence: Information Determination — The public relies on a functioning shortcut — deferring to experts/authorities — to judge policy claims that exceed most people's direct domain literacy. That shortcut fails at the population level whenever authorities visibly disagree or compete for confidence, and it's currently unclear whether the failure is because most people lack the literacy to adjudicate independently, or because the contexts in which claims reach them (soundbites, debates, compressed news cycles) strip out what even literate people would need to adjudicate — or because disagreement gets resolved by identity/motivated reasoning rather than either literacy or context.\n    - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n    - Signal \"Economist?\": Generally officals and SMEs certainty even when problems/solutions are uncertain\n  • Evidence: Information Overload — There is no shared civic infrastructure — no common source, venue, or channel — where local political information circulates. Both signals point to an absence of a shared informational commons at the local level: national/federal information crowds out local, and there's no common space where local facts would even live if someone looked for them.\n    - Signal \"Information Asymmetry?\": Hard to find out about local elections; too much national/federal\n    - Signal \"Shared Truth - or Spaces for Information\": Lack of common spaces or sources for shared factual information\n\n## Pattern: I have an opinon- now what\nAcross all three, there is no verifiable record connecting local civic input to local outcomes — neither citizens deciding whether to act, nor anyone checking whether officials responded, has access to evidence that effort at the local level actually produces effect. The recurring condition isn't \"no information\" broadly — it's specifically the absence of an outcome-verification link.\n\n  • Evidence: Why act? — Citizens carry a rational-ignorance heuristic calibrated to federal-scale politics (\"my input won't change anything\") and apply it by default to local politics — where the actual effort-to-impact ratio is far more favorable — and nothing corrects this misapplication because no local information exists to show them their local leverage is different.\n    - Signal \"Access to Engagement\": Across demos\n    - Signal \"Rational ignorance\": Individually rational to stay uninformed since one vote is rarely decisive, voting is a collective action problem\n  • Evidence: Who is responsible for feedback loops? — Policymakers can act (or fail to act) on constituent opinion without any public record existing to verify whether they did — the accountability mechanism itself is invisible, because the data that would let anyone check \"did they listen\" is not made public.\n    - Signal \"Democratization of Public Opinion Data\": Public opinion is essentials to hold policy makers accountable to constituents but the data is not public\n    - Signal \"Access to Engagement\": Across demos\n  • Evidence: Local better? — Before any civic action happens, a person has to judge whether it's \"worth it\" — and something is currently blocking that judgment from being made, whether the blockage is a resource constraint (time), an information gap (what the action would actually accomplish locally), or both together. The mechanism is a stalled cost-benefit judgment, not yet a confirmed cause.\n    - Signal \"Low Local Action\": People don't have the time or information to determine what civic actions are 'worth it'.\n    - Signal \"Access to Engagement\": Across demos\n\n## Pattern: Unscaffolded Reform Drives Voter Withdrawal\nWhen administrators introduce complex new voting mechanics without providing the necessary educational support or neutral candidate data, the resulting cognitive burden causes voters to simply abandon the process.\n\n  • Evidence: Procedural Friction Triggers Civic Withdrawal — Voters facing convoluted voting mechanics, such as ranked-choice rules, and a polluted information environment opt out of participating rather than navigate a system they cannot decode.\n    - Signal \"voter turnout\": people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation\n    - Signal \"Ranked-Choice Confusion Persists\": Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\n  • Evidence: Implementation Outpaces Educational Scaffolding — When administrators deploy new ranked-choice voting structures without providing sufficient public education or unbiased candidate data, voters are left confused by the mechanics and unable to adapt their voting behavior.\n    - Signal \"Ranked-Choice Confusion Persists\": Voters remain confused about how ranked choice voting works and still lack clear, unbiased information about the candidates themselves.\n    - Signal \"Ranked Choice Voting Education\": The implementation of ranked choice voting lacks sufficient public education to help voters understand its systemic benefits and how it changes voting behaviors.\n\n## Pattern: Civic Voids Invite Weaponized Noise\nWhen systemic failures create local information deserts and procedural confusion, bad actors flood the gap with disinformation, causing voters to either withdraw entirely or fall prey to manipulation.\n\n  • Evidence: Local Information Deserts Invite Manipulation — The systemic absence of actionable local candidate data creates an information vacuum, forcing voters to rely on superficial cues like yard signs while leaving them highly vulnerable to targeted disinformation.\n    - Signal \"Local Candidate Information Gaps\": Voters lack easily accessible, actionable information about local county-level candidates, often relying heavily on name recognition from campaign signs.\n    - Signal \"Civic Distrust & Disinformation\": A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\n  • Evidence: Disinformation Exploits Baseline Civic Confusion — Political entities use internet-era disinformation to weaponize voters' lack of procedural literacy, leading impacted populations to either withdraw completely or succumb to manipulated instincts.\n    - Signal \"voter turnout\": people who are impacted by result don't show up to vote.\r\n- no trust in system\r\n- confusion over requirements & process\r\n- misinformation\n    - Signal \"Civic Distrust & Disinformation\": A toxic combination of distrust in voting, a lack of civics literacy, and internet-era disinformation is allowing political entities to manipulate voters' worst instincts.\n\n"}};
